/*
 * The expected results were generated by Matlab 7.11.0.584 (R2010b)
 * 64-bit (glnxa64) on baboon (Debian 6, 6 core Xeon W3690) except those for
 * the total variation-like regularization or with a spatial constraint;
 * those were generated with Python 2.7.10 and numpy 1.8.0rc1 on OS X 10.10.5
 * with a Mac mini (Late 2014)/2.6 GHz i5 as the hardware.  The Matlab code
 * used for JacobiNL3Ddu was this from Eric Branlund (adopted from the 4D code
 * by Muthuvel Arigovindan):

   function [X, cost] = JacobiNL3Ddu ( X, B, Hd, Imn, Diagd, lamratio,  ...
	  			       lampos, lamf, alpha, laml2, PCF, ...
				       NIter, delfrac, type )

        for ind = 1:NIter

                [R, Diag] = Res3D( X, Hd, Diagd, lamf, lamratio, lampos, ...
                                   alpha, laml2, delfrac, type );
                R = B - R;

                U = real(ifftn( PCF.*fftn( (1./Diag).*ifftn(PCF.*fftn(R)) ) ));
                max(X(:))
                max(U(:))

                [alphaw,cost] = LineSearch3D2n ( X, U, Hd, Imn, delfrac, ...
                                                 lamratio, lampos, lamf, ...
                                                 alpha, laml2, type );
                cost

                X = X + alphaw*U;

        end

   return;

 * The Python code used for that was:

def _jacobi_nl_du(x, mask, dsp, b, hd, imn, pcf, diagd, lamf=1.0, alpha=1e4,
                  lamratio=1.0, lampos=1.0, laml2=0.0, lammask=0.0, niter=50,
                  regtype='ma', cost_reporter=None, mask_updater=None,
                  r4d=True):
    for iter in range(0, niter):
        r, diag = _res(x, dsp, hd, diagd, lamf=lamf, alpha=alpha,
                       lamratio=lamratio, lampos=lampos, laml2=laml2,
                       lammask=lammask, mask=mask, regtype=regtype, r4d=r4d)
        r = b - r
        u = numpy.real(
            numpy.fft.ifftn(pcf * numpy.fft.fftn(
                    numpy.fft.ifftn(pcf * numpy.fft.fftn(r)) / diag)))
        beta = _line_search_2n(x, dsp, u, hd, imn, iter, lamf=lamf,
                               alpha=alpha, lamratio=lamratio, lampos=lampos,
                               laml2=laml2, lammask=lammask, mask=mask,
                               regtype=regtype, cost_reporter=cost_reporter,
                               r4d=r4d)
        x += beta * u
        if mask_updater is not None:
            mask_updater(iter + 1, x, mask)

 */
